registerModuleVariants("intimacy.kissing_pull.ch.say_want_her", [{ when: {}, weight: 5, text: ["You say you want her. She makes it obvious. Mouth first, then the rest of her arrives.","You say you want her. She makes it obvious. She kisses like she is rearranging the room around you."] }]);
registerModuleVariants("intimacy.kissing_pull.ch.pull_to_couch", [{ when: {}, weight: 5, text: ["You pull toward the couch. She is already heavier in the walk. Mouth first, then the rest of her arrives.","You pull toward the couch. She is already heavier in the walk. She kisses like she is rearranging the room around you."] }]);
registerModuleVariants("intimacy.kissing_pull.ch.stay_standing", [{ when: {}, weight: 5, text: ["You stay standing. She uses you as furniture. She kisses like she is rearranging the room around you.","You stay standing. She uses you as furniture. The kiss pulls her whole body into the bargain."] }]);
registerModuleVariants("intimacy.kissing_pull.end0", [{ when: {}, weight: 5, text: ["After, she stays where the warmth is. No one rushes the getting up. Mouth first, then the rest of her arrives.","The moment ends by getting quieter, not by leaving. She kisses like she is rearranging the room around you."] }]);
registerModuleVariants("intimacy.kissing_pull.end1", [{ when: {}, weight: 5, text: ["A few words. Mostly she stays. The talking can wait. The kiss pulls her whole body into the bargain.","She says something small and true, then keeps her weight on you. Mouth first, then the rest of her arrives."] }]);
registerModuleVariants("intimacy.kissing_pull.end2", [{ when: {}, weight: 5, text: ["She eases off, smoothed and satisfied, and looks at you like a finished plate. She kisses like she is rearranging the room around you.","Dress fixed, expression pleased. She already knows you will do this again. The kiss pulls her whole body into the bargain."] }]);
